"""Keep Web composition candidate repair in the fitted model feature space."""

from __future__ import annotations

from dataclasses import replace
from types import MethodType
from typing import Any

_INSTALLED = False


def _composition_model_columns(optimizer: Any) -> list[str]:
    """Return composition columns regenerated by ``transform_compositions``."""

    columns: list[str] = []
    transformers = dict(
        getattr(optimizer, "composition_transformers_", None) or {}
    )
    for transformer in transformers.values():
        columns.extend(
            str(name)
            for name in (getattr(transformer, "feature_names_", None) or ())
        )
    return list(dict.fromkeys(columns))


def _replace_candidate_result(
    result: Any,
    *,
    candidates: Any,
    acq_value: Any,
) -> Any:
    """Replace candidate values on dataclass-like and mutable result objects."""

    try:
        from dataclasses import replace as dataclass_replace

        return dataclass_replace(
            result,
            candidates=candidates,
            acq_value=acq_value,
        )
    except TypeError:
        result.candidates = candidates
        result.acq_value = acq_value
        return result


def _install_candidate_repair(optimizer: Any) -> None:
    """Repair compositions without duplicating Fraction representation columns."""

    if getattr(optimizer, "_web_composition_candidate_repair", False):
        return
    original = optimizer.candidate

    def candidate_with_repair(self: Any, *args: Any, **kwargs: Any) -> Any:
        result = original(*args, **kwargs)
        if not kwargs.get("return_result"):
            return result

        from bochan.tabular.converter import dataframe_to_tensors

        raw_frame = self.candidates_to_dataframe(result.candidates)
        restored = self.inverse_compositions(
            raw_frame,
            repair=True,
            keep_coordinates=False,
        )

        # ``inverse_compositions`` deliberately returns element-fraction columns
        # for display. With the Fraction model representation those columns have
        # the same names as the model inputs. Passing them unchanged to
        # ``transform_compositions`` appends a second copy, and pandas then
        # expands a d-column selection to more than d columns. Drop only the
        # generated model columns before rebuilding the model-space frame.
        transform_source = restored.drop(
            columns=_composition_model_columns(self),
            errors="ignore",
        )
        transformed = self.transform_compositions(transform_source)
        data_config = replace(
            self.data_config,
            input_cols=self.dataset.feature_names,
            target_cols=None,
        )
        repaired_x = dataframe_to_tensors(transformed, data_config).X
        expected_dimension = int(result.candidates.shape[-1])
        if int(repaired_x.shape[-1]) != expected_dimension:
            raise RuntimeError(
                "Composition candidate repair changed the model feature dimension: "
                f"expected {expected_dimension}, got {int(repaired_x.shape[-1])}."
            )

        repaired_acq = result.acq_value
        try:
            import torch

            with torch.no_grad():
                scores = result.acqf(repaired_x.unsqueeze(-2)).detach().reshape(-1)
            if scores.numel() == repaired_x.shape[0]:
                repaired_acq = scores
        except (AttributeError, RuntimeError, TypeError, ValueError):
            pass
        return _replace_candidate_result(
            result,
            candidates=repaired_x,
            acq_value=repaired_acq,
        )

    optimizer.candidate = MethodType(candidate_with_repair, optimizer)
    optimizer._web_composition_candidate_repair = True


def install_composition_candidate_repair_compat() -> None:
    """Install the dimension-safe Web composition candidate-repair adapter."""

    global _INSTALLED
    if _INSTALLED:
        return

    from . import composition_web_support

    composition_web_support._install_candidate_repair = _install_candidate_repair
    _INSTALLED = True


__all__ = [
    "_install_candidate_repair",
    "install_composition_candidate_repair_compat",
]
